CREATE DATABASE IF NOT EXISTS sim_management_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sim_management_db;
CREATE TABLE IF NOT EXISTS roles (id_role INT AUTO_INCREMENT PRIMARY KEY, role_name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS status_user (id_status_user INT AUTO_INCREMENT PRIMARY KEY, status_name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sim_types (id_sim_type INT AUTO_INCREMENT PRIMARY KEY, sim_type VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sim_status (id_sim_status INT AUTO_INCREMENT PRIMARY KEY, sim_status VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS registrations_status (id_registration_status INT AUTO_INCREMENT PRIMARY KEY, status_name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (id_user INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, fullname VARCHAR(150) NOT NULL, phone_number VARCHAR(50), id_role INT NOT NULL, id_status_user INT NOT NULL, failed_login_attempts INT NOT NULL DEFAULT 0, locked_until DATETIME NULL, deleted_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_users_role FOREIGN KEY (id_role) REFERENCES roles(id_role), CONSTRAINT fk_users_status FOREIGN KEY (id_status_user) REFERENCES status_user(id_status_user)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agents (id_agent INT AUTO_INCREMENT PRIMARY KEY, agent_name VARCHAR(150) NOT NULL, contact_phone VARCHAR(50), contact_email VARCHAR(150), address VARCHAR(255), created_by INT NULL, deleted_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_agents_created_by FOREIGN KEY (created_by) REFERENCES users(id_user) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers (id_customer INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, passport_number VARCHAR(50) NOT NULL UNIQUE, nationality VARCHAR(100), date_of_birth DATE, passport_expiry_date DATE NULL, phone_number VARCHAR(50), selfie_photo VARCHAR(500), passport_photo VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS history_sim_card_file (id_file INT AUTO_INCREMENT PRIMARY KEY, file_name VARCHAR(255) NOT NULL, id_agent INT NULL, uploaded_by INT NULL, total_rows INT DEFAULT 0, success_rows INT DEFAULT 0, failed_rows INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_history_agent FOREIGN KEY (id_agent) REFERENCES agents(id_agent) ON DELETE SET NULL, CONSTRAINT fk_history_uploaded_by FOREIGN KEY (uploaded_by) REFERENCES users(id_user) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sim_cards (id_sim INT AUTO_INCREMENT PRIMARY KEY, iccid VARCHAR(32) NOT NULL UNIQUE, imsi VARCHAR(32) NOT NULL UNIQUE, qr_code TEXT NULL, activation_code VARCHAR(255) NULL, id_package INT NULL, package VARCHAR(150) NULL, phone_number VARCHAR(50), id_sim_type INT NULL, id_sim_status INT NOT NULL DEFAULT 1, imported_by INT NULL, id_file INT NULL, imported_at DATETIME NULL, link_url VARCHAR(500) NULL, deleted_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_sim_type FOREIGN KEY (id_sim_type) REFERENCES sim_types(id_sim_type) ON DELETE SET NULL, CONSTRAINT fk_sim_status FOREIGN KEY (id_sim_status) REFERENCES sim_status(id_sim_status), CONSTRAINT fk_sim_imported_by FOREIGN KEY (imported_by) REFERENCES users(id_user) ON DELETE SET NULL, CONSTRAINT fk_sim_file FOREIGN KEY (id_file) REFERENCES history_sim_card_file(id_file) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS packages (id_package INT AUTO_INCREMENT PRIMARY KEY, package_name VARCHAR(150) NOT NULL, description VARCHAR(255), duration_days INT NOT NULL, price DECIMAL(14,2) NOT NULL, currency VARCHAR(10) NOT NULL DEFAULT 'LAK', is_active TINYINT(1) NOT NULL DEFAULT 1, created_by INT NULL, deleted_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_packages_created_by FOREIGN KEY (created_by) REFERENCES users(id_user) ON DELETE SET NULL) ENGINE=InnoDB;
ALTER TABLE sim_cards ADD CONSTRAINT fk_sim_package FOREIGN KEY (id_package) REFERENCES packages(id_package) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS registrations (id_registration INT AUTO_INCREMENT PRIMARY KEY, id_registration_status INT NOT NULL DEFAULT 1, id_customer INT NOT NULL, id_sim INT NOT NULL, id_agent INT NOT NULL, id_package INT NULL, registered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_by INT NULL, reviewed_at DATETIME NULL, notes VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, CONSTRAINT fk_reg_status FOREIGN KEY (id_registration_status) REFERENCES registrations_status(id_registration_status), CONSTRAINT fk_reg_customer FOREIGN KEY (id_customer) REFERENCES customers(id_customer), CONSTRAINT fk_reg_sim FOREIGN KEY (id_sim) REFERENCES sim_cards(id_sim), CONSTRAINT fk_reg_agent FOREIGN KEY (id_agent) REFERENCES agents(id_agent), CONSTRAINT fk_reg_package FOREIGN KEY (id_package) REFERENCES packages(id_package) ON DELETE SET NULL, CONSTRAINT fk_reg_reviewer FOREIGN KEY (reviewed_by) REFERENCES users(id_user) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id_payment INT AUTO_INCREMENT PRIMARY KEY, id_registration INT NOT NULL, id_package INT NOT NULL, amount DECIMAL(14,2) NOT NULL, currency VARCHAR(10) NOT NULL DEFAULT 'LAK', payment_method VARCHAR(50) NOT NULL DEFAULT 'Cash', payment_status VARCHAR(30) NOT NULL DEFAULT 'Pending', transaction_reference VARCHAR(150) NULL, paid_at DATETIME NULL, notes VARCHAR(500) NULL, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_payment_reg FOREIGN KEY (id_registration) REFERENCES registrations(id_registration), CONSTRAINT fk_payment_package FOREIGN KEY (id_package) REFERENCES packages(id_package), CONSTRAINT fk_payment_user FOREIGN KEY (created_by) REFERENCES users(id_user) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS refresh_tokens (id_refresh_token BIGINT AUTO_INCREMENT PRIMARY KEY, id_user INT NOT NULL, token_hash VARCHAR(128) NOT NULL UNIQUE, issued_at DATETIME DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, last_activity_at DATETIME NULL, revoked TINYINT(1) NOT NULL DEFAULT 0, ip_address VARCHAR(64), user_agent TEXT, device_name VARCHAR(150), CONSTRAINT fk_refresh_user FOREIGN KEY (id_user) REFERENCES users(id_user) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id_audit_log BIGINT AUTO_INCREMENT PRIMARY KEY, id_user INT NULL, action VARCHAR(100) NOT NULL, target_entity VARCHAR(100), target_id VARCHAR(100), metadata JSON NULL, ip_address VARCHAR(64), user_agent TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_user FOREIGN KEY (id_user) REFERENCES users(id_user) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id_notification BIGINT AUTO_INCREMENT PRIMARY KEY, id_user INT NOT NULL, title VARCHAR(200) NOT NULL, message VARCHAR(500) NOT NULL, type VARCHAR(50) DEFAULT 'info', is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notification_user FOREIGN KEY (id_user) REFERENCES users(id_user) ON DELETE CASCADE) ENGINE=InnoDB;
